{
  "result": {
    "kind": "MISSION_REQUEST",
    "text": "Lancer une mission autonome pour inventorier, analyser et proposer un rapport priorisé d'amélioration de la documentation d'architecture du projet ICOS.",
    "action": {
      "kind": "cle-action",
      "description": "Exécuter les étapes : (1) lister les fichiers de docs/architecture, (2) examiner leur contenu pour cohérence, lacunes et obsolescence, (3) synthétiser un rapport classé par impact/effort.",
      "riskLevel": "read_only"
    },
    "goal": {
      "title": "Analyse et amélioration de la documentation d'architecture du projet ICOS",
      "objective": "Inventorier les documents de docs/architecture, évaluer leur cohérence, identifier les lacunes et sections obsolètes, puis produire un rapport priorisé des améliorations recommandées (impact / effort).",
      "successCriteria": [
        "Liste complète des fichiers présents dans docs/architecture",
        "Analyse détaillée de chaque document (structure, clarté, pertinence, à jour)",
        "Identification des incohérences, lacunes et contenus obsolètes",
        "Rapport présentant les améliorations recommandées, classées par impact attendu et effort estimé"
      ],
      "constraints": [
        "Lecture seule : aucun fichier ne doit être modifié",
        "Le livrable est exclusivement le rapport d'analyse"
      ],
      "riskLevel": "read_only"
    }
  },
  "memorySuggestions": [],
  "intent": "start_autonomous_mission"
}
